import React, { useContext, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "./AuthContext";

const GOOGLE_CLIENT_ID = process.env.REACT_APP_GOOGLE_CLIENT_ID;

export default function Login() {
  const { saveToken } = useContext(AuthContext);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [rememberMe, setRememberMe] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const [matrixColumns, setMatrixColumns] = useState([]);

  useEffect(() => {
    // Initialize matrix rain columns
    const columnCount = Math.floor(window.innerWidth / 20);
    const columns = Array.from({ length: columnCount }, (_, i) => ({
      id: i,
      characters: [],
      speed: Math.random() * 3 + 2,
      opacity: Math.random() * 0.5 + 0.3
    }));
    setMatrixColumns(columns);

    // Animate matrix rain
    const interval = setInterval(() => {
      setMatrixColumns(prev => prev.map(col => ({
        ...col,
        characters: [
          String.fromCharCode(0x30A0 + Math.random() * 96),
          ...col.characters.slice(0, 20)
        ]
      })));
    }, 50);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (window.google && GOOGLE_CLIENT_ID) {
      window.google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: handleGoogleResponse,
      });

      window.google.accounts.id.renderButton(
        document.getElementById("googleSignInDiv"),
        {
          theme: "outline",
          size: "large",
          width: "400",
          text: "continue_with",
          shape: "rectangular",
        }
      );
    }
  }, []);

  const handleGoogleResponse = async (response) => {
    const googleToken = response.credential;
    setIsLoading(true);

    try {
      const res = await fetch("http://127.0.0.1:8000/auth/google", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id_token: googleToken }),
      });

      const data = await res.json();
      if (!res.ok) {
        alert("Google login failed");
        return;
      }

      saveToken(data.token, data.user);
      navigate("/join");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogin = async () => {
    if (!email || !password) {
      alert("Please fill in all fields");
      return;
    }

    setIsLoading(true);
    try {
      const res = await fetch("http://127.0.0.1:8000/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      const data = await res.json();

      if (!res.ok) {
        alert(data.detail || "Invalid credentials");
        return;
      }

      saveToken(data.token, data.user);
      navigate("/join");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      background: "#0d0208",
      padding: "20px",
      fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
      position: "relative",
      overflow: "hidden"
    }}>
      {/* Matrix Rain Background */}
      <div style={{
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: "radial-gradient(ellipse at center, #001a0e 0%, #0d0208 100%)"
      }}>
        {matrixColumns.map((col, i) => (
          <div
            key={col.id}
            style={{
              position: "absolute",
              left: `${i * 20}px`,
              top: 0,
              fontSize: "14px",
              fontFamily: "monospace",
              color: `rgba(0, 255, 65, ${col.opacity})`,
              textShadow: "0 0 8px rgba(0, 255, 65, 0.8)",
              whiteSpace: "pre",
              pointerEvents: "none",
              lineHeight: "20px"
            }}
          >
            {col.characters.map((char, idx) => (
              <div
                key={idx}
                style={{
                  opacity: 1 - (idx * 0.05),
                  color: idx === 0 ? "#00ff41" : `rgba(0, 255, 65, ${1 - idx * 0.05})`
                }}
              >
                {char}
              </div>
            ))}
          </div>
        ))}
      </div>

      {/* Glowing grid overlay */}
      <div style={{
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundImage: `
          linear-gradient(rgba(0, 255, 65, 0.03) 1px, transparent 1px),
          linear-gradient(90deg, rgba(0, 255, 65, 0.03) 1px, transparent 1px)
        `,
        backgroundSize: "50px 50px",
        pointerEvents: "none"
      }} />

      {/* Scanning line effect */}
      <div style={{
        position: "absolute",
        width: "100%",
        height: "2px",
        background: "linear-gradient(90deg, transparent, rgba(0, 255, 65, 0.8), transparent)",
        boxShadow: "0 0 20px rgba(0, 255, 65, 0.5)",
        animation: "scan 4s linear infinite"
      }} />

      <style>{`
        @keyframes scan {
          0% { top: 0; }
          100% { top: 100%; }
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes glow {
          0%, 100% { box-shadow: 0 0 20px rgba(0, 255, 65, 0.3); }
          50% { box-shadow: 0 0 40px rgba(0, 255, 65, 0.6); }
        }
        input:focus {
          outline: none;
          border-color: #00ff41;
          box-shadow: 0 0 0 3px rgba(0, 255, 65, 0.1);
        }
        .hover-lift {
          transition: all 0.3s ease;
        }
        .hover-lift:hover {
          transform: translateY(-2px);
          box-shadow: 0 8px 32px rgba(0, 255, 65, 0.2);
        }
        button:disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }
      `}</style>

      <div style={{
        width: "480px",
        background: "rgba(13, 2, 8, 0.85)",
        backdropFilter: "blur(10px)",
        padding: "48px",
        borderRadius: "16px",
        boxShadow: "0 8px 32px rgba(0, 255, 65, 0.2), inset 0 0 40px rgba(0, 255, 65, 0.05)",
        border: "1px solid rgba(0, 255, 65, 0.2)",
        animation: "fadeIn 0.5s ease-out, glow 3s ease-in-out infinite",
        position: "relative",
        zIndex: 10
      }}
      className="hover-lift">
        
        {/* Header */}
        <div style={{ textAlign: "center", marginBottom: "32px" }}>
          <h1 style={{
            fontSize: "28px",
            fontWeight: "700",
            color: "#00ff41",
            marginBottom: "8px",
            textShadow: "0 0 10px rgba(0, 255, 65, 0.5)"
          }}>
            Welcome back
          </h1>
          <p style={{
            color: "#5fff7d",
            fontSize: "15px",
            opacity: 0.8
          }}>
            Log in to your account
          </p>
        </div>

        {/* Email Field */}
        <div style={{ marginBottom: "20px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#00ff41",
            marginBottom: "8px"
          }}>
            Email address
          </label>
          <input
            type="email"
            placeholder="Enter your email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleLogin()}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "8px",
              border: "1px solid rgba(0, 255, 65, 0.3)",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "rgba(0, 0, 0, 0.3)",
              color: "#00ff41"
            }}
          />
        </div>

        {/* Password Field */}
        <div style={{ marginBottom: "16px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#00ff41",
            marginBottom: "8px"
          }}>
            Password
          </label>
          <input
            type="password"
            placeholder="Enter your password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleLogin()}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "8px",
              border: "1px solid rgba(0, 255, 65, 0.3)",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "rgba(0, 0, 0, 0.3)",
              color: "#00ff41"
            }}
          />
        </div>

        {/* Remember + Forgot */}
        <div style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "24px"
        }}>
          <label style={{
            display: "flex",
            alignItems: "center",
            cursor: "pointer",
            fontSize: "14px",
            color: "#5fff7d"
          }}>
            <input
              type="checkbox"
              checked={rememberMe}
              onChange={(e) => setRememberMe(e.target.checked)}
              style={{
                width: "16px",
                height: "16px",
                marginRight: "8px",
                cursor: "pointer",
                accentColor: "#00ff41"
              }}
            />
            Remember me
          </label>
          <a href="#" style={{
            color: "#00ff41",
            fontWeight: "500",
            fontSize: "14px",
            textDecoration: "none",
            textShadow: "0 0 5px rgba(0, 255, 65, 0.5)"
          }}>
            Forgot password?
          </a>
        </div>

        {/* Sign in button */}
        <button
          onClick={handleLogin}
          disabled={isLoading}
          style={{
            width: "100%",
            background: "rgba(0, 255, 65, 0.1)",
            color: "#00ff41",
            padding: "14px",
            borderRadius: "8px",
            fontSize: "16px",
            fontWeight: "600",
            border: "1px solid #00ff41",
            cursor: "pointer",
            transition: "all 0.3s ease",
            boxShadow: "0 0 20px rgba(0, 255, 65, 0.3)",
            textShadow: "0 0 5px rgba(0, 255, 65, 0.5)"
          }}
          onMouseOver={(e) => {
            if (!isLoading) {
              e.target.style.background = "#00ff41";
              e.target.style.color = "#000";
              e.target.style.textShadow = "none";
            }
          }}
          onMouseOut={(e) => {
            e.target.style.background = "rgba(0, 255, 65, 0.1)";
            e.target.style.color = "#00ff41";
            e.target.style.textShadow = "0 0 5px rgba(0, 255, 65, 0.5)";
          }}
        >
          {isLoading ? "ACCESSING..." : "LOG IN"}
        </button>

        {/* Divider */}
        <div style={{
          textAlign: "center",
          margin: "24px 0",
          color: "#5fff7d",
          fontSize: "14px",
          position: "relative",
          opacity: 0.6
        }}>
          <div style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: "50%",
            height: "1px",
            background: "rgba(0, 255, 65, 0.2)"
          }} />
          <span style={{
            position: "relative",
            background: "rgba(13, 2, 8, 0.85)",
            padding: "0 16px"
          }}>
            — Or continue with —
          </span>
        </div>

        {/* Google Sign-In Button */}
        <div
          id="googleSignInDiv"
          style={{
            display: "flex",
            justifyContent: "center",
            marginBottom: "16px"
          }}
        ></div>

        {/* Signup link */}
        <div style={{
          textAlign: "center",
          marginTop: "24px",
          fontSize: "14px",
          color: "#5fff7d"
        }}>
          Don't have an account?{" "}
          <a
            href="/signup"
            style={{
              color: "#00ff41",
              fontWeight: "600",
              textDecoration: "none",
              textShadow: "0 0 5px rgba(0, 255, 65, 0.5)"
            }}
          >
            Sign up here
          </a>
        </div>

        {/* Load Google script */}
        <script src="https://accounts.google.com/gsi/client" async defer></script>
      </div>
    </div>
  );
}
